package hr.statistika.tracker;

import org.junit.Test;
import java.time.LocalDate;
import static org.junit.Assert.*;
import static hr.statistika.tracker.Models.*;

public class DomainTest {
    private Data data() { Data d=new Data();Client c=new Client();c.firstName="Ana";c.lastName="Horvat";d.clients.add(c);Project p=new Project();p.clientId=c.id;p.price=30000L;d.projects.add(p);return d; }
    private Payment payment(Data d,long amount,String date) { Payment p=new Payment();p.projectId=d.projects.get(0).id;p.amount=amount;p.paymentDate=date;d.payments.add(p);return p; }
    @Test public void moneyUsesExactCentsAndCroatianSeparators() {assertEquals(123456,Domain.parseMoney("1.234,56 €"));assertEquals(30,Domain.parseMoney("0,30"));assertEquals(30000,Domain.parseMoney("300"));}
    @Test public void moneyRejectsNegativeAndFractionalCents() {for(String value:new String[]{"-1","1,234","NaN","","1e3"}){try{Domain.parseMoney(value);fail(value);}catch(IllegalArgumentException expected){}}}
    @Test public void datesAreStrictIncludingLeapYears() {assertEquals("2024-02-29",Domain.parseDate("29.02.2024."));for(String value:new String[]{"29.02.2026.","31.04.2026.","32.10.2026."}){try{Domain.parseDate(value);fail(value);}catch(IllegalArgumentException expected){}}}
    @Test public void doneAndPartiallyPaidStayIndependent() {Data d=data();Project p=d.projects.get(0);payment(d,10000,"2026-10-04");Domain.changeStatus(p,ProjectStatus.DONE,LocalDate.of(2026,10,4));assertEquals(ProjectStatus.DONE,p.status);assertEquals(PaymentStatus.PARTIALLY_PAID,Domain.paymentStatus(d,p));assertEquals(20000,Domain.remaining(d,p));assertEquals("2026-10-04",p.completedDate);}
    @Test public void threePaymentsCloseProjectAndPriceChangesRecalculate() {Data d=data();Project p=d.projects.get(0);payment(d,10000,"2026-10-04");payment(d,10000,"2026-10-12");payment(d,10000,"2026-10-15");assertEquals(30000,Domain.paid(d,p));assertEquals(PaymentStatus.PAID,Domain.paymentStatus(d,p));p.price=35000L;assertEquals(5000,Domain.remaining(d,p));assertEquals(PaymentStatus.PARTIALLY_PAID,Domain.paymentStatus(d,p));}
    @Test public void unknownPriceDoesNotLookPaidAndAllowsPayments() {Data d=data();Project p=d.projects.get(0);p.price=null;payment(d,5000,"2026-10-04");assertEquals(PaymentStatus.UNKNOWN,Domain.paymentStatus(d,p));assertEquals(0,Domain.remaining(d,p));assertEquals(5000,Domain.paid(d,p));}
    @Test public void overpaymentIsAllowedAndRemainingClamped() {Data d=data();Project p=d.projects.get(0);payment(d,32000,"2026-10-04");assertEquals(PaymentStatus.PAID,Domain.paymentStatus(d,p));assertEquals(0,Domain.remaining(d,p));assertEquals(2000,Domain.overpayment(d,p));}
    @Test public void archivedDebtStillCountsAndSoftDeleteDoesNot() {Data d=data();Project p=d.projects.get(0);p.status=ProjectStatus.ARCHIVED;payment(d,10000,"2026-10-04");assertEquals(20000,Domain.outstanding(d));p.deletedAt=Domain.timestamp();assertEquals(0,Domain.outstanding(d));assertEquals(0,Domain.monthlyRevenue(d,2026)[9]);assertEquals(1,d.payments.size());}
    @Test public void revenueUsesPaymentDateAcrossYearsAndTwelveMonths() {Data d=data();Project p=d.projects.get(0);p.price=50000L;p.createdDate="2026-12-20";payment(d,10000,"2026-12-20");payment(d,40000,"2027-01-10");long[] y2026=Domain.monthlyRevenue(d,2026),y2027=Domain.monthlyRevenue(d,2027);assertEquals(12,y2026.length);assertEquals(10000,y2026[11]);assertEquals(0,y2026[0]);assertEquals(40000,y2027[0]);assertEquals(0,y2027[11]);}
    @Test public void reopeningResetsCompletionAndArchivingPreservesIt() {Data d=data();Project p=d.projects.get(0);Domain.changeStatus(p,ProjectStatus.DONE,LocalDate.of(2026,10,4));Domain.changeStatus(p,ProjectStatus.ARCHIVED,LocalDate.of(2026,10,5));assertEquals("2026-10-04",p.completedDate);Domain.changeStatus(p,ProjectStatus.IN_PROGRESS,LocalDate.of(2026,10,6));assertNull(p.completedDate);Domain.changeStatus(p,ProjectStatus.DONE,LocalDate.of(2026,10,7));assertEquals("2026-10-07",p.completedDate);}
    @Test public void overdueAppliesOnlyToWorkStillOpen() {Data d=data();Project p=d.projects.get(0);p.deadline="2026-10-02";LocalDate today=LocalDate.of(2026,10,4);assertTrue(Domain.overdue(p,today));assertEquals("Kasni 2 dana",Domain.deadlineLabel(p,today));p.status=ProjectStatus.DONE;assertFalse(Domain.overdue(p,today));}
    @Test public void searchFindsInstitutionAndIgnoresAccents() {Data d=data();d.clients.get(0).institution="Medicinski fakultet";d.projects.get(0).title="Statistička analiza";assertTrue(Domain.matches(d,d.projects.get(0),"statisticka"));assertTrue(Domain.matches(d,d.projects.get(0),"medicinski"));assertTrue(Domain.matches(d,d.projects.get(0),"HORVAT"));}
    @Test public void suggestedPaymentTypeUsesClosingBalance() {Data d=data();Project p=d.projects.get(0);assertEquals(PaymentType.DEPOSIT,Domain.suggestedType(d,p,10000));payment(d,10000,"2026-10-04");assertEquals(PaymentType.PARTIAL,Domain.suggestedType(d,p,5000));assertEquals(PaymentType.FINAL,Domain.suggestedType(d,p,20000));}
    @Test public void zeroPriceIsFinanciallyClosedWithoutFakePayment() {Data d=data();Project p=d.projects.get(0);p.price=0L;assertEquals(PaymentStatus.PAID,Domain.paymentStatus(d,p));assertEquals(0,Domain.remaining(d,p));assertTrue(d.payments.isEmpty());}
}
